<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require dirname(__DIR__).'/private/content-store.php';
function doc(string $file):DOMDocument{$html=file_get_contents($file);$d=new DOMDocument('1.0','UTF-8');libxml_use_internal_errors(true);$d->loadHTML('<?xml encoding="utf-8"?>'.$html);libxml_clear_errors();return $d;}
function text(DOMNode $n,string $query):string{$x=(new DOMXPath($n->ownerDocument))->query($query,$n);return $x&&$x->length?trim($x->item(0)->textContent):'';}
function normalize_path(string $v):string{if(str_starts_with($v,'../assets/'))return '/assets/'.substr($v,10);if(str_starts_with($v,'assets/'))return '/'.$v;return $v;}
function body_for(string $file,string $fallback):string{
 if(!is_file($file))$file=str_replace('/../articles/','/articles/',$file);
 $html=$fallback;if(is_file($file)){$d=doc($file);$xp=new DOMXPath($d);$node=$xp->query('//*[contains(concat(" ",normalize-space(@class)," ")," ridewire-article-body ") or contains(concat(" ",normalize-space(@class)," ")," spotlight-article ")]')->item(0);if($node){$html='';foreach($node->childNodes as $child)$html.=$d->saveHTML($child);}}
 $d=new DOMDocument('1.0','UTF-8');libxml_use_internal_errors(true);$d->loadHTML('<?xml encoding="utf-8"?><div id="root">'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);libxml_clear_errors();$xp=new DOMXPath($d);
 foreach($xp->query('//*[@src or @href]') as $el)foreach(['src','href'] as $attr)if($el->hasAttribute($attr)){$v=$el->getAttribute($attr);if(str_starts_with($v,'../assets/'))$el->setAttribute($attr,normalize_path($v));}
 $node=$d->getElementById('root');$out='';if($node)foreach($node->childNodes as $child)$out.=$d->saveHTML($child);return $out;
}
function add(PDO $pdo,string $section,array $data):bool{$check=$pdo->prepare('SELECT 1 FROM rw_content_items WHERE slug=?');$check->execute([$data['slug']]);if($check->fetchColumn()){if(in_array('--refresh-current-static',$GLOBALS['argv']??[],true))$pdo->prepare('UPDATE rw_content_items SET body_html=? WHERE slug=?')->execute([$data['body_html'],$data['slug']]);return false;}$keys=['section','slug','title','category','summary','body_html','image','image_alt','image_caption','country','discipline','highlight','source_url','published_at','status','sort_order'];$values=[$section,$data['slug'],$data['title'],$data['category'],$data['summary'],$data['body_html'],$data['image'],$data['image_alt'],$data['image_caption'],$data['country'],$data['discipline'],$data['highlight'],$data['source_url'],$data['published_at'],$data['status'],$data['sort_order']];$now=$GLOBALS['nowSql'];$q=$pdo->prepare('INSERT INTO rw_content_items('.implode(',',$keys).',created_at,updated_at) VALUES('.implode(',',array_fill(0,count($keys),'?')).','.$now.','.$now.')');$q->execute($values);return true;}
$base=dirname(__DIR__);$inserted=0;
foreach(['news'=>[$base.'/Pages/news.html','scene-news-card','../articles/news/'],'spotlight'=>[$base.'/Pages/spotlight.html','spotlight-rider-card','../articles/spotlight/']] as $section=>[$file,$class,$folder]){$d=doc($file);$xp=new DOMXPath($d);foreach($xp->query('//*[contains(concat(" ",normalize-space(@class)," ")," '.$class.' ")]') as $card){$link=$section==='spotlight'?$card:$xp->query('.//a[1]',$card)->item(0);if(!$link)continue;$href=$link->getAttribute('href');$slug=pathinfo(parse_url($href,PHP_URL_PATH)??'',PATHINFO_FILENAME);if(!$slug)continue;$title=text($card,'.//h3|.//h2');$img=$xp->query('.//img[1]',$card)->item(0);$image=$img?normalize_path($img->getAttribute('src')):'';$alt=$img?$img->getAttribute('alt'):'';$caption=text($card,'.//figcaption');$paragraphs=[];foreach($xp->query('.//div[contains(@class,"scene-news-copy") or contains(@class,"spotlight-rider-card-copy")]/p[not(contains(@class,"kicker"))]',$card) as $p)$paragraphs[]='<p>'.htmlspecialchars(trim($p->textContent),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</p>';$cat=text($card,'.//*[contains(@class,"card-kicker")]');$summary=$section==='spotlight'?text($card,'.//div[contains(@class,"spotlight-rider-card-copy")]/p[not(contains(@class,"kicker"))]'):strip_tags($paragraphs[0]??'');$fallback=$section==='spotlight'?'<p>'.htmlspecialchars($summary,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</p>':implode('',$paragraphs);$body=body_for($base.'/'.$folder.$slug.'.html',$fallback);$published='';if(preg_match('/\b(\d{1,2})\s+([A-Z]{3})\s+(\d{4})\b/i',$cat,$m)){$dt=DateTime::createFromFormat('!d M Y',$m[1].' '.$m[2].' '.$m[3]);if($dt)$published=$dt->format('Y-m-d');}$data=['slug'=>$slug,'title'=>$title,'category'=>$cat,'summary'=>$summary,'body_html'=>$body,'image'=>$image,'image_alt'=>$alt,'image_caption'=>$caption,'country'=>'','discipline'=>$section==='news'?(str_contains(strtolower($cat),'racing')?'racing':'freestyle'):'','highlight'=>'','source_url'=>'','published_at'=>$published,'status'=>'published','sort_order'=>$inserted];if(add($pdo,$section,$data))$inserted++;}}
$d=doc($base.'/Pages/riders.html');$xp=new DOMXPath($d);foreach($xp->query('//*[contains(concat(" ",normalize-space(@class)," ")," rider-database-card ")]') as $card){$name=text($card,'.//h2');if(!$name)continue;$slug=preg_replace('/[^a-z0-9]+/','-',strtolower(iconv('UTF-8','ASCII//TRANSLIT',$name)?:$name));$img=$xp->query('.//img[1]',$card)->item(0);$meta=[];foreach($xp->query('.//*[contains(@class,"rider-card-meta")]/span',$card) as $span)$meta[]=trim($span->textContent);$ps=[];foreach($xp->query('.//div[contains(@class,"rider-database-copy")]/p',$card) as $p)$ps[]='<p>'.htmlspecialchars(trim($p->textContent),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</p>';$source=$xp->query('.//a[contains(@class,"rider-card-link")]',$card)->item(0);$data=['slug'=>$slug,'title'=>$name,'category'=>'Rider profile','summary'=>strip_tags($ps[0]??''),'body_html'=>implode('',$ps),'image'=>$img?normalize_path($img->getAttribute('src')):'','image_alt'=>$img?$img->getAttribute('alt'):'','image_caption'=>text($card,'.//figcaption'),'country'=>$meta[0]??'','discipline'=>$meta[1]??'','highlight'=>text($card,'.//*[contains(@class,"rider-highlight")]'),'source_url'=>$source&&preg_match('~^https://~',$source->getAttribute('href'))?$source->getAttribute('href'):'','published_at'=>'','status'=>'published','sort_order'=>$inserted];if(add($pdo,'rider',$data))$inserted++;}
echo "Imported {$inserted} published content entries (existing slugs skipped).".PHP_EOL;
